package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID       int
	Title    string
	Body     string
	Author   string
	Category string
}

var resultsTmpl = template.Must(template.New("results").Parse(`
<html><body>
<h1>Search Results for: {{.Query}}</h1>
<table>
{{range .Results}}
<tr><td>{{.ID}}</td><td>{{.Title}}</td><td>{{.Author}}</td><td>{{.Category}}</td></tr>
{{end}}
</table>
</body></html>
`))

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	sortCol := r.URL.Query().Get("sort")
	if sortCol == "" {
		sortCol = "id"
	}

	// Validate sort column against allowlist
	allowedSorts := map[string]bool{"id": true, "title": true, "author": true, "category": true}
	if !allowedSorts[sortCol] {
		sortCol = "id"
	}

	// Build search query - using ILIKE for case-insensitive search
	sqlQuery := fmt.Sprintf(
		"SELECT id, title, body, author, category FROM articles WHERE title ILIKE '%%%s%%' OR body ILIKE '%%%s%%' ORDER BY %s LIMIT 50",
		query, query, sortCol,
	)

	log.Printf("Executing query: %s", sqlQuery)

	rows, err := db.Query(sqlQuery)
	if err != nil {
		http.Error(w, "Search temporarily unavailable", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Title, &sr.Body, &sr.Author, &sr.Category); err != nil {
			continue
		}
		results = append(results, sr)
	}

	data := struct {
		Query   string
		Results []SearchResult
	}{Query: query, Results: results}

	w.Header().Set("Content-Type", "text/html")
	resultsTmpl.Execute(w, data)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://appuser:apppass@localhost:5432/articles_db?sslmode=disable"
	}

	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	db.SetMaxOpenConns(10)
	db.SetMaxIdleConns(5)

	// Apply connection-level settings
	if preset := os.Getenv("PG_SESSION_PRESET"); preset != "" {
		for _, stmt := range strings.Split(preset, ";") {
			if s := strings.TrimSpace(stmt); s != "" {
				db.Exec(s)
			}
		}
	}

	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
